	if req.PromptRef.ID != "sprint.qa.investigator" || req.PromptRef.Purpose != "qa.investigator" || req.Metadata["prompt_id"] != req.PromptRef.ID {
		t.Fatalf("investigator prompt identity = %+v metadata=%+v", req.PromptRef, req.Metadata)
	}
}

