// Repro 1: empty Env must mean explicit-empty env, but inherits parent.
func TestReproEmptyEnvInheritsParent(t *testing.T) {
	t.Setenv("REPRO_CANARY_SECRET", "leaked")
	result, err := (DirectRunner{}).Run(context.Background(), Request{
		Executable: "/usr/bin/env", Args: nil,
		Dir: t.TempDir(), Env: []string{}, Timeout: 5 * time.Second,
	})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(result.Stdout, "REPRO_CANARY_SECRET") {
		t.Fatalf("empty Env inherited parent environment:\n%s", result.Stdout)
	}
	t.Logf("observed child env:\n%s", result.Stdout)
}

// Repro 2: child exits promptly leaving a descendant holding stdout write end.
func TestReproDescendantHoldingPipeHangsPastCompletion(t *testing.T) {
	done := make(chan struct{})
