package process

import (
	"context"
	"testing"
	"time"
)

func TestReproTailLossSmallOverflow(t *testing.T) {
	const total = 100 * 1024 // > 64KiB pipe buffer, written promptly then child exits
	losses := 0
	for attempt := 0; attempt < 5; attempt++ {
		result, err := (DirectRunner{}).Run(context.Background(), Request{
			Executable: "/bin/sh",
			Args:       []string{"-c", "awk 'BEGIN{for(i=0;i<102400;i++)printf \"A\"}'"},
			Dir:        t.TempDir(), Env: []string{"PATH=/usr/bin:/bin"},
			Timeout:    30 * time.Second,
			Progress:   func(Event) { time.Sleep(15 * time.Millisecond) },
		})
		if err != nil {
			t.Fatalf("attempt %d: err=%v", attempt, err)
		}
		got := len(result.Stdout)
		t.Logf("attempt %d: got %d of %d, truncated=%v", attempt, got, total, result.StdoutTruncated)
		if got != total && !result.StdoutTruncated {
			losses++
		}
	}
	if losses == 0 {
		t.Logf("no silent losses observed in 5 attempts")
	} else {
		t.Fatalf("SILENT TAIL LOSS in %d/5 attempts: capture short without truncation flag", losses)
	}
}
EOF
cd /tmp/opencode/processrepro && go test -v -run 'TestReproTailLossSmallOverflow' -timeout 120s 2>&1 | tail -10

