package process

import (
	"context"
	"errors"
	"io"
	"sync"
	"testing"
	"time"
)

func TestReproInstrumented(t *testing.T) {
	var mu sync.Mutex
	type ev struct {
		t   time.Duration
		n   int
		err error
	}
	start := time.Now()
	var events []ev
	debugCopyHook = func(stream string, n int, err error) {
		mu.Lock()
		events = append(events, ev{time.Since(start), n, err})
		mu.Unlock()
	}
	defer func() { debugCopyHook = nil }()

	result, err := (DirectRunner{}).Run(context.Background(), Request{
		Executable: "/bin/sh",
		Args:       []string{"-c", "awk 'BEGIN{for(i=0;i<102400;i++)printf \"A\"}'"},
		Dir:        t.TempDir(), Env: []string{"PATH=/usr/bin:/bin"},
		Timeout: 30 * time.Second,
		Progress: func(Event) { time.Sleep(15 * time.Millisecond) },
	})
	if err != nil {
		t.Fatalf("err=%v", err)
	}
	mu.Lock()
	defer mu.Unlock()
	t.Logf("captured=%d", len(result.Stdout))
	for i, e := range events {
		if i < 6 || e.err != nil || i >= len(events)-2 {
			t.Logf("event %d: t=%v n=%d err=%v", i, e.t.Round(time.Millisecond), e.n, e.err)
		}
	}
	var readErrs int
	for _, e := range events {
		if e.err != nil && !errors.Is(e.err, io.EOF) {
			readErrs++
		}
	}
	t.Logf("total read calls=%d, non-EOF read errors=%d", len(events), readErrs)
}
EOF
