package process

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"sync"
	"testing"
	"time"
)

// Replicates DirectRunner's exact structure, but the drain goroutine is
// artificially descheduled mid-loop to emulate CPU starvation.
func TestReproDrainDescheduledPastClose(t *testing.T) {
	var gate sync.Mutex
	gate.Lock() // drain blocks trying to lock after first chunk
	release := func() { gate.Unlock() }

	cmd := exec.Command("/bin/sh", "-c", "awk 'BEGIN{for(i=0;i<70000;i++)printf \"A\"}'")
	cmd.Dir = t.TempDir()
	cmd.Env = []string{"PATH=/usr/bin:/bin"}
	stdout, _ := cmd.StdoutPipe()
	capture := &bytes.Buffer{}
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	waited := make(chan error, 1)
	go func() { waited <- cmd.Wait() }()
	drained := make(chan struct{})
	go func() {
		defer close(drained)
		buf := make([]byte, 32*1024)
		first := true
		for {
			n, err := stdout.Read(buf)
			if n > 0 {
				capture.Write(buf[:n])
				if first {
					first = false
					gate.Lock() // deschedule until after Wait() closes the fd
				}
			}
			if err != nil {
				fmt.Printf("drain final read: n=%d err=%v captured=%d\n", n, err, capture.Len())
				return
			}
		}
	}()
	select {
	case werr := <-waited:
		t.Logf("cmd.Wait returned (child reaped, parent pipes now closed): err=%v", werr)
		time.Sleep(50 * time.Millisecond)
		release()
	case <-time.After(5 * time.Second):
		t.Fatal("timeout")
	}
	<-drained
	t.Logf("captured %d of 70000 bytes", capture.Len())
	if capture.Len() != 70000 {
		t.Fatalf("TAIL LOST: captured %d of 70000 bytes without any truncation signal", capture.Len())
	}
}
EOF
